-- A NULL key part takes no data but adds the null bitmap, which moves the data to offset
-- 16: `(NULL, text)` holds 2 684 characters, where `(text)` alone holds 2 692.
-- @setup
CREATE TABLE t (n text, a text);
CREATE INDEX t_i ON t (n, a);
INSERT INTO t VALUES (NULL, '');
-- @test
SELECT n IS NULL, length(a) FROM t;
